// dynreads.tsv is GENERATED by `cigate plan-dynreads` from the AST: one row per Go file that holds a read, open or walk
// call whose path is not a compile-time constant after folding (dynamicReads names the kinds):
//
//	package<TAB>site<TAB>classes
//
// classes is the union of the measured walk rows a walk-callback path comes from, or `unexpressed` when any call of the
// file reads a path the tool cannot bound. Temp-rooted, own-directory and measured-walk calls need no row. The planner
// plans FULL for any non-Go change while an `unexpressed` row exists or the table differs from the generated one;
// plan-reads fails the difference. A hand edit may only narrow an `unexpressed` row to a class list (a reviewed diff).
// A `_test.go` site selects its package, any other site the package's importers' tests too.
const (
	dynReadsFile   = "dynreads.tsv"
	dynUnexpressed = "unexpressed"
	dynExcludedPkg = "internal/cigates/affected" // the guard's own reads run in the always-run static leg
)

type dynRow struct {
	pkg, site string
	classes   []string
	line      int
}

func (d dynRow) scope() string {
	if strings.HasSuffix(d.site, "_test.go") {
		return scopeTest
	}
	return scopeCode
}

func loadDynReads(dir string, known map[string]bool) ([]dynRow, error) {
	rows, lines, err := readTSV(filepath.Join(dir, dynReadsFile), 3)
	if err != nil {
		return nil, err
	}
	var out []dynRow
	seen := map[string]bool{}
	for i, r := range rows {
		d := dynRow{pkg: r[0], site: r[1], classes: splitList(r[2]), line: lines[i]}
		where := fmt.Sprintf("%s:%d", dynReadsFile, d.line)
		if path.Clean(d.pkg) != d.pkg || strings.HasPrefix(d.pkg, "/") || strings.HasPrefix(d.pkg, "../") {
			return nil, fmt.Errorf("%s: package %q is not a clean repository path", where, d.pkg)
		}
		if !strings.HasSuffix(d.site, ".go") || strings.Contains(d.site, "/") {
			return nil, fmt.Errorf("%s: site %q is not a Go file base name", where, d.site)
		}
		for _, c := range d.classes {
			if c == dynUnexpressed && len(d.classes) == 1 {
				continue
			}
			if !known[c] {
				return nil, fmt.Errorf("%s: class %q is not in %s", where, c, classesFile)
			}
		}
		k := d.pkg + "/" + d.site
		if seen[k] {
			return nil, fmt.Errorf("%s: %s already has a row", where, k)
		}
		seen[k] = true
		out = append(out, d)
	}
	return out, nil
}

func (t *tables) dynRow(pkg, site string) (dynRow, bool) {
	for _, d := range t.dynReads {
		if d.pkg == pkg && d.site == site {
			return d, true
		}
	}
	return dynRow{}, false
}

func (d dynRow) unexpressed() bool { return len(d.classes) == 1 && d.classes[0] == dynUnexpressed }

func (d dynRow) cell() string {
	if len(d.classes) == 0 {
		return "-"
	}
	return strings.Join(d.classes, ",")
}

// generateDynReads is the dynreads.tsv the tree calls for, with one sample call per row for messages.
func generateDynReads(reads []Read, t *tables) ([]dynRow, map[string]string) {
	walkClasses := map[string]map[string]bool{} // pkg/site -> classes of its non-static walk rows
	for _, w := range t.walks {
		k := w.pkg + "/" + w.site
		if walkClasses[k] == nil {
			walkClasses[k] = map[string]bool{}
		}
		if w.scope != scopeStatic {
			for _, c := range w.classes {
				walkClasses[k][c] = true
			}
		}
	}
	type acc struct {
		classes     map[string]bool
		unexpressed bool
		sample      string
	}
	rows := map[string]*acc{}
	for _, r := range reads {
		if !r.Dynamic || r.Package == dynExcludedPkg || r.Kind == kindTemp || r.Kind == kindOwn {
			continue
		}
		site := path.Base(r.File)
		k := r.Package + "/" + site
		wc, measured := walkClasses[k]
		call := r.Literal[:strings.IndexByte(r.Literal, '(')]
		if measured && (walkCalls[call] || call == "filepath.Walk" || call == "fs.WalkDir") {
			continue
		}
		a := rows[k]
		if a == nil {
			a = &acc{classes: map[string]bool{}, sample: fmt.Sprintf("%s:%d %s", r.File, r.Line, r.Literal)}
			rows[k] = a
		}
		if r.Kind == kindWalkPath && measured {
			for c := range wc {
				a.classes[c] = true
			}
			continue
		}
		if !a.unexpressed {
			a.sample = fmt.Sprintf("%s:%d %s", r.File, r.Line, r.Literal)
		}
		a.unexpressed = true
	}
	var out []dynRow
	samples := map[string]string{}
	for k, a := range rows {
		i := strings.LastIndexByte(k, '/')
		d := dynRow{pkg: k[:i], site: k[i+1:]}
		if a.unexpressed {
			d.classes = []string{dynUnexpressed}
		} else {
			d.classes = sortedKeys(a.classes)
			if len(d.classes) == 0 {
				continue
			}
		}
		out = append(out, d)
		samples[k] = a.sample
	}
	sort.Slice(out, func(i, j int) bool { return out[i].pkg+"/"+out[i].site < out[j].pkg+"/"+out[j].site })
	return out, samples
}

// dynDiff compares the checked-in rows with the generated ones: one line per difference. A checked-in class list (or
// `-`) where the generated row is `unexpressed` is a reviewed narrowing, not a difference.
func dynDiff(generated []dynRow, samples map[string]string, t *tables) []string {
	have := map[string]dynRow{}
	for _, d := range t.dynReads {
		have[d.pkg+"/"+d.site] = d
	}
	var out []string
	for _, g := range generated {
		k := g.pkg + "/" + g.site
		h, ok := have[k]
		delete(have, k)
		switch {
		case !ok:
			out = append(out, fmt.Sprintf("%s: undeclared dynamic read: %s; the generated row is %s\t%s\t%s (cigate plan-dynreads)", g.pkg, samples[k], g.pkg, g.site, g.cell()))
		case h.cell() == g.cell():
		case g.unexpressed() && !h.unexpressed():
		default:
			out = append(out, fmt.Sprintf("%s:%d: %s/%s is %s, the generated row is %s (%s)", dynReadsFile, h.line, g.pkg, g.site, h.cell(), g.cell(), samples[k]))
		}
	}
	for k, h := range have {
		out = append(out, fmt.Sprintf("%s:%d: %s holds no read the generator keeps (no non-constant, non-temp, non-own, unmeasured path)", dynReadsFile, h.line, k))
	}
	sort.Strings(out)
	return out
}

// planDynamic is the planner's view: the differences between the table and the tree, read at plan time.
func planDynamic(root string, t *tables) ([]string, error) {
	if _, err := os.Stat(root); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	reads, err := ScanReads(root)
	if err != nil {
		return nil, err
	}
	gen, samples := generateDynReads(reads, t)
	return dynDiff(gen, samples, t), nil
}

// PlanDynReads prints the generated dynreads.tsv for the tree at --root.
func PlanDynReads(args []string, stdout, stderr io.Writer) int {
	fl := flag.NewFlagSet("plan-dynreads", flag.ContinueOnError)
	fl.SetOutput(stderr)
	root := fl.String("root", "", "repository root")
	tablesDir := fl.String("tables", "", "directory of classes.tsv and walks.tsv (default ROOT/internal/cigates/affected)")
	if err := fl.Parse(args); err != nil {
		return 2
	}
	if *root == "" {
		fmt.Fprintln(stderr, "plan-dynreads: --root is required")
		return 2
	}
	dir := *tablesDir
	if dir == "" {
		dir = filepath.Join(*root, filepath.FromSlash(plannerDir))
	}
	t, err := loadTables(dir)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	reads, err := ScanReads(*root)
	if err != nil {
		fmt.Fprintln(stderr, err)
		return 1
	}
	gen, _ := generateDynReads(reads, t)
	fmt.Fprintln(stdout, "# GENERATED by `cigate plan-dynreads --root .`; a hand edit may only narrow an `unexpressed` row (dynreads.go)")
	fmt.Fprintln(stdout, "# package\tsite\tclasses")
	for _, d := range gen {
		fmt.Fprintf(stdout, "%s\t%s\t%s\n", d.pkg, d.site, d.cell())
	}
	return 0
}

// logDynamicReads writes one line per package with dynreads.tsv rows: its declared classes against the classes the change
// reaches, and whether the change selected it.
func (t *tables) logDynamicReads(w io.Writer, reached, selected map[string]bool) {
	if w == nil || len(reached) == 0 {
		return
	}
	declared := map[string]map[string]bool{}
	for _, d := range t.dynReads {
		if declared[d.pkg] == nil {
			declared[d.pkg] = map[string]bool{}
		}
		for _, c := range d.classes {
			declared[d.pkg][c] = true
		}
	}
	var pkgs []string
	for p := range declared {
		pkgs = append(pkgs, p)
	}
	sort.Strings(pkgs)
	reach := sortedKeys(reached)
	for _, p := range pkgs {
		state := "not selected"
		if selected[p] {
			state = "selected"
		}
		fmt.Fprintf(w, "dynamic read in %s: classes declared %v, reachable %v; %s\n", p, sortedKeys(declared[p]), reach, state)
	}
}

// Kinds of a read, open or walk call whose path is not a compile-time constant after folding:
//
//	temp      rooted at t.TempDir/os.MkdirTemp/os.CreateTemp with only constant, ".."-free parts after the root: not the repo
//	own       rooted at the package's own directory (a constant relative path without "..", or runtime.Caller's file dir):
//	          the package owns it, so a change there selects the package already
//	walk      the walk call of a site measured by walks.tsv
//	walkpath  a path a measured walk hands to its callback: it reads what the walk row's classes say
//	dyn       anything else: the generated dynreads row is `unexpressed`
const (
	kindTemp     = "temp"
	kindOwn      = "own"
	kindWalk     = "walk"
	kindWalkPath = "walkpath"
	kindDyn      = "dyn"
	kindConst    = "const"
)

var tempRoot = map[string]bool{"t.TempDir": true, "b.TempDir": true, "tb.TempDir": true, "f.TempDir": true, "os.MkdirTemp": true, "os.TempDir": true}

type dynScope struct {
	parent   *dynScope
	locals   map[string]string // local name -> kind of every value assigned to it ("" when the values disagree)
	walkPath map[string]bool   // names of walk-callback path parameters
}

func (sc *dynScope) lookup(name string) (string, bool) {
	for s := sc; s != nil; s = s.parent {
		if s.walkPath[name] {
			return kindWalkPath, true
		}
		if k, ok := s.locals[name]; ok {
			return k, true
		}
	}
	return "", false
}

func hasDotDot(e ast.Expr) bool {
	found := false
	ast.Inspect(e, func(n ast.Node) bool {
		if lit, ok := n.(*ast.BasicLit); ok && lit.Kind == token.STRING {
			if v, err := strconv.Unquote(lit.Value); err == nil && (strings.Contains(v, "..") || strings.HasPrefix(v, "/")) {
				found = true
			}
		}
		return true
	})
	return found
}

// pathKind classifies a path expression; consts are the package's constant names.
func pathKind(e ast.Expr, sc *dynScope, consts map[string]bool) string {
	if isConstPath(e, consts) {
		return kindConst
	}
	switch x := e.(type) {
	case *ast.ParenExpr:
		return pathKind(x.X, sc, consts)
	case *ast.Ident:
		if k, ok := sc.lookup(x.Name); ok && k != "" {
			return k
		}
		return kindDyn
	case *ast.CallExpr:
		name := callName(x.Fun)
		if tempRoot[name] {
			return kindTemp
		}
		if sel, ok := x.Fun.(*ast.SelectorExpr); ok && sel.Sel.Name == "Name" && len(x.Args) == 0 {
			if id, ok := sel.X.(*ast.Ident); ok {
				if k, _ := sc.lookup(id.Name); k == kindTemp {
					return kindTemp
				}
			}
		}
		switch name {
		case "filepath.Join", "path.Join":
			if len(x.Args) == 0 {
				return kindDyn
			}
			root := pathKind(x.Args[0], sc, consts)
			rest := true
			for _, a := range x.Args[1:] {
				if pathKind(a, sc, consts) != kindConst || hasDotDot(a) {
					rest = false
				}
			}
			switch root {
			case kindConst:
				if !hasDotDot(x.Args[0]) {
					return kindOwn
				}
			case kindOwn:
				return kindOwn
			case kindTemp, kindWalkPath:
				if rest {
					return root
				}
			}
			return kindDyn
		case "filepath.Dir", "path.Dir", "filepath.Clean", "path.Clean", "filepath.Abs", "filepath.FromSlash", "filepath.ToSlash":
			if len(x.Args) == 1 {
				k := pathKind(x.Args[0], sc, consts)
				if k == kindConst && !hasDotDot(x.Args[0]) {
					return kindOwn
				}
				return k
			}
		}
	}
	return kindDyn
}

// assignedKinds folds the locals of one function body: a local is the kind of every value assigned to it, and nothing
// when two assignments disagree. runtime.Caller's file result is the package's own directory.
func assignedKinds(body ast.Node, sc *dynScope, consts map[string]bool) {
	set := func(name, k string) {
		if name == "_" {
			return
		}
		if old, ok := sc.locals[name]; ok && old != k {
			sc.locals[name] = ""
			return
		}
		sc.locals[name] = k
	}
	for pass := 0; pass < 3; pass++ {
		ast.Inspect(body, func(n ast.Node) bool {
			switch a := n.(type) {
			case *ast.AssignStmt:
				if len(a.Rhs) == 1 && len(a.Lhs) > 1 {
					if call, ok := a.Rhs[0].(*ast.CallExpr); ok && callName(call.Fun) == "runtime.Caller" && len(a.Lhs) >= 2 {
						if id, ok := a.Lhs[1].(*ast.Ident); ok {
							set(id.Name, kindOwn)
						}
						return true
					}
					if call, ok := a.Rhs[0].(*ast.CallExpr); ok && (callName(call.Fun) == "os.MkdirTemp" || callName(call.Fun) == "os.CreateTemp") {
						if id, ok := a.Lhs[0].(*ast.Ident); ok {
							set(id.Name, kindTemp)
						}
						return true
					}
					for _, l := range a.Lhs {
						if id, ok := l.(*ast.Ident); ok {
							set(id.Name, kindDyn)
						}
					}
					return true
				}
				for i, l := range a.Lhs {
					id, ok := l.(*ast.Ident)
					if !ok || i >= len(a.Rhs) {
						continue
					}
					set(id.Name, pathKind(a.Rhs[i], sc, consts))
				}
			case *ast.ValueSpec:
				for i, id := range a.Names {
					if i < len(a.Values) {
						set(id.Name, pathKind(a.Values[i], sc, consts))
					} else {
						set(id.Name, kindDyn)
					}
				}
			case *ast.RangeStmt:
				for _, e := range []ast.Expr{a.Key, a.Value} {
					if id, ok := e.(*ast.Ident); ok {
						set(id.Name, kindDyn)
					}
				}
			}
			return true
		})
	}
}

// dynamicReads lists every read, open or walk call of a file whose path is not a compile-time constant, with its kind.
func dynamicReads(fset *token.FileSet, f *ast.File, rel string, consts map[string]bool) []Read {
	pkg := path.Dir(rel)
	test := strings.HasSuffix(rel, "_test.go")
	var out []Read
	var visit func(n ast.Node, sc *dynScope)
	visit = func(n ast.Node, sc *dynScope) {
		ast.Inspect(n, func(m ast.Node) bool {
			if m == n {
				return true
			}
			switch x := m.(type) {
			case *ast.FuncLit:
				inner := &dynScope{parent: sc, locals: map[string]string{}, walkPath: map[string]bool{}}
				assignedKinds(x.Body, inner, consts)
				visit(x.Body, inner)
				return false
			case *ast.CallExpr:
				name := callName(x.Fun)
				if (walkCalls[name] || name == "filepath.Walk" || name == "fs.WalkDir") && len(x.Args) > 0 {
					if lit, ok := x.Args[len(x.Args)-1].(*ast.FuncLit); ok && len(lit.Type.Params.List) > 0 && len(lit.Type.Params.List[0].Names) > 0 {
						inner := &dynScope{parent: sc, locals: map[string]string{}, walkPath: map[string]bool{lit.Type.Params.List[0].Names[0].Name: true}}
						assignedKinds(lit.Body, inner, consts)
						for _, a := range x.Args[:len(x.Args)-1] {
							visit(a, sc)
						}
						record(fset, &out, x, name, sc, consts, pkg, rel, test)
						visit(lit.Body, inner)
						return false
					}
				}
				record(fset, &out, x, name, sc, consts, pkg, rel, test)
			}
			return true
		})
	}
	for _, d := range f.Decls {
		fd, ok := d.(*ast.FuncDecl)
		if !ok || fd.Body == nil {
			continue
		}
		sc := &dynScope{locals: map[string]string{}, walkPath: map[string]bool{}}
		assignedKinds(fd.Body, sc, consts)
		visit(fd.Body, sc)
	}
	return out
}

func record(fset *token.FileSet, out *[]Read, call *ast.CallExpr, name string, sc *dynScope, consts map[string]bool, pkg, rel string, test bool) {
	if !dynamicCalls[name] || len(call.Args) == 0 {
		return
	}
	arg := call.Args[0]
	if strings.HasPrefix(name, "fs.") && len(call.Args) > 1 {
		arg = call.Args[1]
	}
	k := pathKind(arg, sc, consts)
	if k == kindConst {
		return
	}
	*out = append(*out, Read{Package: pkg, File: rel, Line: fset.Position(call.Pos()).Line, Test: test, Dynamic: true, Kind: k,
		Literal: name + "(" + exprText(fset, arg) + ")"})
}
